clamp:
def clamp(value, low, high):
    """Return value limited to the inclusive range [low, high]."""
    if value < low:
        return low
    if value > high:
        return high
    return value

last_index:
def last_index(items):
    """Return the index of the final element, or -1 for an empty list."""
    return len(items) - 1

chunk:
def chunk(items, size):
    """Split items into consecutive lists of at most `size` elements."""
    if size <= 0:
        raise ValueError("size must be positive")
    items = list(items)
    return [items[i:i + size] for i in range(0, len(items), size)]

median:
def median(numbers):
    """Return the median of a non-empty list of numbers (mean of the middle two when even)."""
    ordered = sorted(numbers)
    count = len(ordered)
    if count == 0:
        raise ValueError("median of an empty list is undefined")
    middle = count // 2
    if count % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

truncate:
def truncate(text, limit):
    """Return text unchanged when it fits in `limit` characters, otherwise cut it
    and end with an ellipsis so the result is exactly `limit` characters long."""
    if len(text) <= limit:
        return text
    ellipsis = "..."
    if limit <= len(ellipsis):
        return ellipsis[:max(limit, 0)]
    return text[:limit - len(ellipsis)] + ellipsis

count_words:
def count_words(text):
    """Return the number of whitespace-separated words; an empty or blank string has none."""
    return len(text.split())

is_leap:
def is_leap(year):
    """True when the year is a leap year in the Gregorian calendar."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

percent:
def percent(part, whole):
    """Return part as a percentage of whole, rounded to one decimal; 0.0 when whole is 0."""
    if whole == 0:
        return 0.0
    return round(part * 100.0 / whole, 1)

dedupe:
def dedupe(items):
    """Remove duplicates, keeping the first occurrence and the original order."""
    seen = set()
    unseen = []
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unseen:
                continue
            unseen.append(item)
        result.append(item)
    return result

initials:
def initials(full_name):
    """Return the uppercase initials of each word: 'ada lovelace' -> 'AL'."""
    return "".join(word[0].upper() for word in full_name.split())

clip_index:
def clip_index(index, length):
    """Return a valid index into a sequence of `length` items, clipped into range;
    a negative index counts from the end as Python does."""
    if length <= 0:
        return 0
    if index < 0:
        index += length
    if index < 0:
        return 0
    if index > length - 1:
        return length - 1
    return index

parse_duration:
def parse_duration(text):
    """Parse '1h30m' or '45s' into whole seconds. Missing units are zero."""
    import re
    units = {"h": 3600, "m": 60, "s": 1}
    total = 0
    for amount, unit in re.findall(r"(\d+)\s*([hms])", text.strip().lower()):
        total += int(amount) * units[unit]
    return total

balanced:
def balanced(text):
    """True when every round bracket in the text is opened before it is closed and all are closed."""
    depth = 0
    for character in text:
        if character == "(":
            depth += 1
        elif character == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

average_or_zero:
def average_or_zero(numbers):
    """Return the mean, or 0 when the list is empty."""
    numbers = list(numbers)
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)
